#define HEAD                                                                \
  "{\"version\":\"2.1.0\",\"$schema\":\"https://docs.oasis-open.org/sarif/" \
  "sarif/v2.1.0/errata01/os/schemas/sarif-schema-2.1.0.json\",\"runs\":[{"  \
  "\"tool\":{\"driver\":{\"name\":\"nopinion\",\"informationUri\":"         \
  "\"https://github.com/embedded-brains/nopinion\"}},"

/* ST [%o0], %g1 is 0xc2220000 and ADD %g1, 1, %g1 is 0x82006001 */
#define DEFINITE_AT_0                                                   \
  "\"instructions\":[{\"offset\":0,\"word\":3257008128},{\"offset\":4," \
  "\"word\":2181062657},{\"offset\":8,\"word\":3257008128}]"

#define POSSIBLE_AT_0                                                   \
  "\"instructions\":[{\"offset\":0,\"word\":3257008128},{\"offset\":4," \
  "\"word\":2181062657},null]"

#define POSSIBLE_AT_16                                                    \
